3	//! RFC 7523 `private_key_jwt` client authentication for the token endpoint, shared by the
4	//! `authorization_code` and `refresh_token` grants.
5	//!
6	//! The AS metadata has always advertised `private_key_jwt`, but until this module existed a
7	//! confidential client's `client_assertion` was silently ignored by serde and the client
8	//! treated as public — meaning a leaked authorization code or refresh token was exchangeable
9	//! without the client's key (2026-08-03 interop audit, gap 2). The registered
10	//! `token_endpoint_auth_method` in the client's metadata document now decides what this
11	//! endpoint requires: `none` clients must not send an assertion, `private_key_jwt` clients
12	//! must send a valid one.
13	//!
14	//! Assertion checks follow RFC 7523 §3 with the atproto OAuth profile's narrowing: ES256
15	//! only, `iss` = `sub` = `client_id`, `aud` = this AS's issuer (the token-endpoint URL is
16	//! also accepted — both appear in the wild), `exp` required, and a 30-second clock tolerance
17	//! (the reference implementation's zero-tolerance `iat` check is a documented interop trap —
18	//! bluesky-social/atproto#4474). The verification key comes from the metadata's inline
19	//! `jwks` or its `jwks_uri`; the latter is a client-controlled URL, so it gets the same
20	//! transport policy as `client_id` itself (https except loopback, no credentials) and is
21	//! fetched with the SSRF-hardened client, which is the actual guard. `jti` presence
22	//! is required but not replay-tracked: every protected grant is already single-use
23	//! (authorization codes) or rotation-guarded (refresh tokens), so a replayed assertion alone
24	//! wins nothing.
25	
26	use jsonwebtoken::jwk::JwkSet;
27	use jsonwebtoken::{Algorithm, DecodingKey, Validation};
28	use serde::Deserialize;
29	
30	use crate::app::AppState;
31	use crate::db::oauth::{get_oauth_client, ClientMetadata};
32	use crate::routes::oauth_errors::OAuthTokenError;
33	
34	pub(super) const CLIENT_ASSERTION_TYPE_JWT_BEARER: &str =
35	    "urn:ietf:params:oauth:client-assertion-type:jwt-bearer";
36	
37	/// Clock skew tolerated on the assertion's time claims (RFC 7523 permits a few minutes;
38	/// 30 seconds covers real-world drift without meaningfully widening the replay window).
39	const CLOCK_TOLERANCE_SECS: u64 = 30;
40	
41	/// Upper bound on a fetched JWK set. Real key sets are a few hundred bytes; the cap only
42	/// exists so a hostile `jwks_uri` host cannot stream an unbounded body into memory. Matches
43	/// the client-metadata document cap.
44	const MAX_JWKS_BYTES: usize = 64 * 1024;
45	
46	#[derive(Debug, Deserialize)]
47	struct ClientAssertionClaims {
48	    iss: String,
49	    sub: String,
50	    jti: Option<String>,
51	}
52	
53	fn invalid_client(description: impl Into<String>) -> OAuthTokenError {
54	    OAuthTokenError::new_owned("invalid_client", description.into())
55	}
56	
57	/// Enforce the client's registered `token_endpoint_auth_method` for a token request.
58	///
59	/// Reads the client's cached metadata document (resolved and stored at PAR/authorize time;
60	/// an unknown client or one whose stored metadata predates the extended fields is treated
61	/// as a public client, matching the pre-existing behavior for every seeded row).
62	pub(super) async fn authenticate_token_client(
63	    state: &AppState,
64	    client_id: &str,
65	    assertion_type: Option<&str>,
66	    assertion: Option<&str>,
67	) -> Result<(), OAuthTokenError> {
68	    let metadata: ClientMetadata = match get_oauth_client(&state.db, client_id).await {
69	        Ok(Some(row)) => serde_json::from_str(&row.client_metadata).unwrap_or_default(),
70	        Ok(None) => ClientMetadata::default(),
71	        Err(e) => {
72	            tracing::error!(error = %e, "failed to load client metadata for token auth");
73	            return Err(OAuthTokenError::new("server_error", "database error"));
74	        }
75	    };
76	
77	    match metadata
78	        .token_endpoint_auth_method
79	        .as_deref()
80	        .unwrap_or("none")
81	    {
82	        "none" => {
83	            // A public client sending an assertion is a registration/config mismatch the
84	            // client author needs to hear about, not silently ignore.
85	            if assertion.is_some() {
86	                return Err(invalid_client(
87	                    "client is registered with token_endpoint_auth_method \"none\" \
88	                     but sent a client_assertion",
89	                ));
90	            }
91	            Ok(())
92	        }
93	        "private_key_jwt" => {
94	            verify_private_key_jwt(state, client_id, &metadata, assertion_type, assertion).await
95	        }
96	        other => Err(invalid_client(format!(
97	            "unsupported token_endpoint_auth_method \"{other}\""
98	        ))),
99	    }
100	}
101	
102	async fn verify_private_key_jwt(
103	    state: &AppState,
104	    client_id: &str,
105	    metadata: &ClientMetadata,
106	    assertion_type: Option<&str>,
107	    assertion: Option<&str>,
108	) -> Result<(), OAuthTokenError> {
109	    let assertion = assertion.ok_or_else(|| {
110	        invalid_client("client authentication required: missing client_assertion")
111	    })?;
112	    if assertion_type != Some(CLIENT_ASSERTION_TYPE_JWT_BEARER) {
113	        return Err(invalid_client(format!(
114	            "client_assertion_type must be {CLIENT_ASSERTION_TYPE_JWT_BEARER}"
115	        )));
116	    }
117	
118	    let header = jsonwebtoken::decode_header(assertion)
119	        .map_err(|_| invalid_client("client_assertion is not a well-formed JWT"))?;
120	    if header.alg != Algorithm::ES256 {
121	        return Err(invalid_client("client_assertion must be signed with ES256"));
122	    }
123	
124	    let key = resolve_client_key(state, metadata, header.kid.as_deref()).await?;
125	
126	    let issuer = state.config.public_url.trim_end_matches('/').to_string();
127	    let token_url = format!("{issuer}/oauth/token");
128	    let mut validation = Validation::new(Algorithm::ES256);
129	    validation.leeway = CLOCK_TOLERANCE_SECS;
130	    validation.set_audience(&[issuer, token_url]);
131	    validation.set_required_spec_claims(&["exp", "aud"]);
132	
133	    let data = jsonwebtoken::decode::<ClientAssertionClaims>(assertion, &key, &validation)
134	        .map_err(|e| invalid_client(format!("client_assertion rejected: {e}")))?;
135	
136	    if data.claims.iss != client_id || data.claims.sub != client_id {
137	        return Err(invalid_client(
138	            "client_assertion iss and sub must both be the client_id",
139	        ));
140	    }
141	    if data.claims.jti.as_deref().is_none_or(|jti| jti.is_empty()) {
142	        return Err(invalid_client("client_assertion must carry a jti"));
143	    }
144	    Ok(())
145	}
146	
147	/// Resolve the client's assertion-verification key from its metadata: the inline `jwks`
148	/// first, else a policy-checked fetch of `jwks_uri` via the SSRF-hardened client.
149	async fn resolve_client_key(
150	    state: &AppState,
151	    metadata: &ClientMetadata,
152	    kid: Option<&str>,
153	) -> Result<DecodingKey, OAuthTokenError> {
154	    if let Some(jwks) = &metadata.jwks {
155	        let set: JwkSet = serde_json::from_value(jwks.clone())
156	            .map_err(|_| invalid_client("client metadata jwks is not a valid JWK set"))?;
157	        return select_key(&set, kid);
158	    }
159	    if let Some(url) = &metadata.jwks_uri {
160	        let parsed = url::Url::parse(url)
161	            .map_err(|_| invalid_client("client metadata jwks_uri is not a valid URL"))?;
162	        // The URL comes from a client-authored document, so it gets exactly the transport
163	        // policy client_id resolution uses: https, no credentials — with loopback as the one
164	        // place plain http is acceptable. Holding `jwks_uri` to a stricter rule than the
165	        // `client_id` it was fetched from would make a loopback development client
166	        // (explicitly supported by the spec, and by `oauth_client_resolution`) unable to
167	        // publish its keys by URL at all.
168	        //
169	        // The scheme check is not the SSRF control and never was: that is the hardened
170	        // client's connect-time resolver, which refuses loopback and private addresses in
171	        // production regardless of what this allows.
172	        if !parsed.username().is_empty() || parsed.password().is_some() {
173	            return Err(invalid_client(
174	                "client metadata jwks_uri must carry no credentials",
175	            ));
176	        }
177	        if parsed.scheme() != "https" && !crate::auth::oauth_client_resolution::url_is_loopback(url)
178	        {
179	            return Err(invalid_client(
180	                "client metadata jwks_uri must be an https URL",
181	            ));
182	        }
183	        let resp = state
184	            .hardened_http_client
185	            .get(parsed)
186	            .send()
187	            .await
188	            .map_err(|_| invalid_client("failed to fetch client jwks_uri"))?;
189	        if !resp.status().is_success() {
190	            return Err(invalid_client(format!(
191	                "client jwks_uri returned HTTP {}",
192	                resp.status()
193	            )));
194	        }
195	        // The body comes from a host the client names, so it is bounded before it is parsed:
196	        // a real JWK set is a few hundred bytes, and without a cap a hostile (or merely
197	        // broken) key host could stream an unbounded response into memory. The shared client
198	        // already bounds how *long* this can take; this bounds how *large* it can get. Same
199	        // reasoning and same limit as the client-metadata fetch next door.
200	        if resp
201	            .content_length()
202	            .is_some_and(|len| len > MAX_JWKS_BYTES as u64)
203	        {
204	            return Err(invalid_client("client jwks_uri response is too large"));
205	        }
206	        let body = resp
207	            .bytes()
208	            .await
209	            .map_err(|_| invalid_client("failed to read the client jwks_uri response"))?;
210	        // Re-checked after reading: a chunked response carries no content-length to check.
211	        if body.len() > MAX_JWKS_BYTES {
212	            return Err(invalid_client("client jwks_uri response is too large"));
213	        }
214	        let set: JwkSet = serde_json::from_slice(&body)
215	            .map_err(|_| invalid_client("client jwks_uri did not return a valid JWK set"))?;
216	        return select_key(&set, kid);
217	    }
218	    Err(invalid_client(
219	        "client metadata declares private_key_jwt but provides neither jwks nor jwks_uri",
220	    ))
221	}
222	
223	fn select_key(set: &JwkSet, kid: Option<&str>) -> Result<DecodingKey, OAuthTokenError> {
224	    let jwk = match kid {
225	        Some(kid) => set
226	            .keys
227	            .iter()
228	            .find(|k| k.common.key_id.as_deref() == Some(kid)),
229	        // No kid on the assertion: unambiguous only when the set holds exactly one key.
230	        None if set.keys.len() == 1 => set.keys.first(),
231	        None => None,
232	    }
233	    .ok_or_else(|| invalid_client("no matching key in the client's JWK set"))?;
234	    DecodingKey::from_jwk(jwk).map_err(|_| invalid_client("client JWK is not a usable key"))
235	}
