248	    const CLIENT_ID: &str = "https://app.example.com/client-metadata.json";
249	
250	    async fn seed_client(state: &AppState, metadata: serde_json::Value) {
251	        upsert_oauth_client(&state.db, CLIENT_ID, &metadata.to_string())
252	            .await
253	            .unwrap();
254	    }
255	
256	    fn jwk_with_kid(key: &SigningKey, kid: &str) -> serde_json::Value {
257	        let mut jwk = dpop_key_to_jwk(key);
258	        jwk["kid"] = serde_json::Value::String(kid.to_string());
259	        jwk
260	    }
261	
262	    fn confidential_metadata(key: &SigningKey) -> serde_json::Value {
263	        serde_json::json!({
264	            "client_id": CLIENT_ID,
265	            "redirect_uris": ["https://app.example.com/callback"],
266	            "token_endpoint_auth_method": "private_key_jwt",
267	            "jwks": { "keys": [jwk_with_kid(key, "k1")] },
268	        })
269	    }
270	
271	    fn sign_assertion(key: &SigningKey, kid: &str, claims: serde_json::Value) -> String {
272	        let header = serde_json::json!({ "alg": "ES256", "kid": kid });
273	        let hdr = URL_SAFE_NO_PAD.encode(serde_json::to_string(&header).unwrap().as_bytes());
274	        let pay = URL_SAFE_NO_PAD.encode(serde_json::to_string(&claims).unwrap().as_bytes());
275	        let sig_input = format!("{hdr}.{pay}");
276	        let sig: Signature = key.sign(sig_input.as_bytes());
277	        let sig_b64 = URL_SAFE_NO_PAD.encode(sig.to_bytes().as_ref() as &[u8]);
278	        format!("{hdr}.{pay}.{sig_b64}")
279	    }
280	
281	    fn valid_claims(iss_sub: &str) -> serde_json::Value {
282	        serde_json::json!({
283	            "iss": iss_sub,
284	            "sub": iss_sub,
285	            "aud": "https://test.example.com",
286	            "iat": now_secs(),
287	            "exp": now_secs() + 60,
288	            "jti": "assertion-jti-1",
289	        })
290	    }
