444	    /// The `jwks_uri` branch: a client that publishes its keys at a URL rather than inline.
445	    ///
446	    /// Worth its own test because it is the only path in this module that makes an outbound
447	    /// request, and it is a *client-controlled* URL — so it runs through the SSRF-hardened
448	    /// client. Production bakes `allow_loopback = false` into that client, which means this
449	    /// branch cannot be exercised from the hermetic conformance suite (a loopback jwks_uri is
450	    /// correctly refused there); a wiremock server plus `test_state`'s loopback-permitting
451	    /// client is the only place it can be covered at all.
452	    #[tokio::test]
453	    async fn confidential_client_key_is_fetched_from_jwks_uri() {
454	        use wiremock::matchers::{method, path};
455	        use wiremock::{Mock, MockServer, ResponseTemplate};
456	
457	        let state = test_state().await;
458	        let key = SigningKey::random(&mut OsRng);
459	
460	        let server = MockServer::start().await;
461	        Mock::given(method("GET"))
462	            .and(path("/jwks.json"))
463	            .respond_with(ResponseTemplate::new(200).set_body_json(serde_json::json!({
464	                "keys": [jwk_with_kid(&key, "k1")],
465	            })))
466	            .mount(&server)
467	            .await;
468	
469	        seed_client(
470	            &state,
471	            serde_json::json!({
472	                "client_id": CLIENT_ID,
473	                "redirect_uris": ["https://app.example.com/callback"],
474	                "token_endpoint_auth_method": "private_key_jwt",
475	                "jwks_uri": format!("{}/jwks.json", server.uri()),
476	            }),
477	        )
478	        .await;
479	
480	        let assertion = sign_assertion(&key, "k1", valid_claims(CLIENT_ID));
481	        authenticate_token_client(
482	            &state,
483	            CLIENT_ID,
484	            Some(CLIENT_ASSERTION_TYPE_JWT_BEARER),
485	            Some(&assertion),
486	        )
487	        .await
488	        .expect("a key published at jwks_uri must authenticate the assertion");
489	    }
