2	
3	//! Dynamic issuer-key resolution for the auth.md `identity_assertion` flow (ID-JAG verification) —
4	//! the dynamic-trust half of `issuer_trust.rs`'s key resolution, and its sole consumer.
5	//!
6	//! A trusted issuer delivers its signing keys either as an inline PEM (static trust, which never
7	//! touches this module) or as a JWKS URL — `[agent_auth] trusted_issuers[].jwks_url` — fetched and
8	//! cached here. This module owns a `JwksFetcher` abstraction (production `HttpJwksFetcher` +
9	//! injectable test mocks, mirroring the `dns::TxtResolver` pattern) and a TTL cache (`JwksCache`)
10	//! keyed by URL that selects an ID-JAG's `kid` header out of the issuer's key set and hands back
11	//! a `DecodingKey`.
12	//!
13	//! The cache is reachable from public, unauthenticated endpoints (`POST /agent/identity`,
14	//! `POST /agent/event/notify`), where the `kid` comes from an *unverified* JWT header. A per-URL
15	//! refetch cooldown (`[agent_auth] jwks_refetch_cooldown_secs`, stamped per fetch *attempt*)
16	//! bounds how often those requests — or a failing issuer — can force an outbound JWKS fetch.
17	//! Without it, a stream of bogus-`kid` tokens naming a trusted issuer would translate one inbound
18	//! request into one outbound fetch (amplification toward the issuer, wasted work here).
19	
20	use std::collections::HashMap;
21	use std::future::Future;
22	use std::pin::Pin;
23	use std::sync::{Arc, Mutex};
24	use std::time::{Duration, Instant};
25	
26	use jsonwebtoken::jwk::JwkSet;
27	use jsonwebtoken::DecodingKey;
28	
29	/// Error fetching or parsing an issuer JWKS.
30	#[derive(Debug, thiserror::Error)]
31	#[error("JWKS fetch error: {0}")]
32	pub struct JwksError(pub String);
33	
34	/// Abstraction over fetching a JWKS document from an issuer's `jwks_url`.
35	///
36	/// Object-safe (uses `Pin<Box<dyn Future>>`) so `dyn JwksFetcher` works behind `Arc`. The
37	/// production impl is [`HttpJwksFetcher`]; tests inject a mock so no real network I/O runs.
38	pub trait JwksFetcher: Send + Sync {
39	    fn fetch<'a>(
40	        &'a self,
41	        url: &'a str,
42	    ) -> Pin<Box<dyn Future<Output = Result<JwkSet, JwksError>> + Send + 'a>>;
43	}
44	
45	/// Production [`JwksFetcher`] backed by the shared reqwest client.
46	pub struct HttpJwksFetcher {
47	    client: reqwest::Client,
48	}
49	
50	impl HttpJwksFetcher {
51	    pub fn new(client: reqwest::Client) -> Self {
52	        Self { client }
53	    }
54	}
55	
56	impl JwksFetcher for HttpJwksFetcher {
57	    fn fetch<'a>(
58	        &'a self,
59	        url: &'a str,
60	    ) -> Pin<Box<dyn Future<Output = Result<JwkSet, JwksError>> + Send + 'a>> {
61	        Box::pin(async move {
62	            let resp = self
63	                .client
64	                .get(url)
65	                .send()
66	                .await
67	                .map_err(|e| JwksError(format!("request to {url} failed: {e}")))?;
68	            if !resp.status().is_success() {
69	                return Err(JwksError(format!(
70	                    "issuer JWKS endpoint {url} returned HTTP {}",
71	                    resp.status()
72	                )));
73	            }
74	            resp.json::<JwkSet>()
75	                .await
76	                .map_err(|e| JwksError(format!("issuer JWKS at {url} is not a valid JWK set: {e}")))
77	        })
78	    }
79	}
80	
81	/// One cached JWKS document plus the monotonic instant it was fetched (for TTL expiry).
82	struct CachedJwks {
83	    fetched_at: Instant,
84	    set: JwkSet,
85	}
86	
87	/// Per-URL cache slot: the last successful fetch (if any) plus the instant of the last fetch
88	/// *attempt* — success or failure — which drives the refetch cooldown. Tracking attempts rather
89	/// than successes means a failing issuer (e.g. one timing out) is also retried at most once per
90	/// cooldown instead of once per inbound request.
91	struct CacheSlot {
92	    last_attempt: Instant,
93	    fetched: Option<CachedJwks>,
94	}
95	
96	/// What a locked cache consultation decided; the fetch itself always runs outside the lock.
97	enum Consult {
98	    /// A fresh cached set contains the key.
99	    Key(DecodingKey),
100	    /// A fresh cached set lacks the key and the cooldown forbids refetching: the `kid` is
101	    /// negatively cached as unknown until the cooldown lapses.
102	    KnownAbsent,
103	    /// No usable cached set and the cooldown forbids refetching (the last attempt failed, or
104	    /// another request is fetching right now): fail fast instead of piling on.
105	    FailFast,
106	    /// The caller may fetch; the attempt has already been stamped into the slot.
107	    Fetch,
108	}
109	
110	/// A TTL cache over a [`JwksFetcher`], keyed by JWKS URL.
111	///
112	/// Shared via `Arc` in `AppState`. A verification consults the cache first; on a miss, a stale
113	/// entry, or a fetched-but-absent `kid` (a rotated key not yet cached), it fetches and re-selects —
114	/// so a key rotation is picked up by the first request that names the new `kid` once the refetch
115	/// cooldown (below) allows it.
116	///
117	/// `refetch_cooldown` is the minimum interval between fetch *attempts* for a given URL, bounding
118	/// the outbound amplification available to unauthenticated requests that name arbitrary `kid`s
119	/// (see the module header). Within the cooldown an unknown `kid` resolves from the last fetched
120	/// set (→ `Ok(None)`) and a fetch failure keeps failing fast (→ `Err`). The cooldown should stay
121	/// well below `ttl`; a genuine key rotation is picked up after at most one cooldown of
122	/// `invalid_grant` responses. Zero disables the cooldown (every miss fetches).
123	pub struct JwksCache {
124	    fetcher: Arc<dyn JwksFetcher>,
125	    ttl: Duration,
126	    refetch_cooldown: Duration,
127	    entries: Mutex<HashMap<String, CacheSlot>>,
128	}
129	
130	impl JwksCache {
131	    pub fn new(fetcher: Arc<dyn JwksFetcher>, ttl: Duration, refetch_cooldown: Duration) -> Self {
132	        Self {
133	            fetcher,
134	            ttl,
135	            refetch_cooldown,
136	            entries: Mutex::new(HashMap::new()),
137	        }
138	    }
139	
140	    /// Resolve the decoding key for `(url, kid)`.
141	    ///
142	    /// Returns `Ok(Some(key))` when a matching key is found, `Ok(None)` when the cached-or-fetched
143	    /// key set does not contain `kid` — an unknown signing key, which the caller maps to
144	    /// `invalid_grant` — or `Err` when the JWKS could not be fetched/parsed (transport/operator
145	    /// failure, mapped to `server_error`) or a recent failed attempt is still inside the refetch
146	    /// cooldown.
147	    ///
148	    /// A fresh cached set that already contains `kid` is used without any network call; otherwise
149	    /// the JWKS is fetched at most once per `refetch_cooldown` (never while holding the lock),
150	    /// cached, and the key re-selected.
151	    pub async fn decoding_key(
152	        &self,
153	        url: &str,
154	        kid: Option<&str>,
155	    ) -> Result<Option<DecodingKey>, JwksError> {
156	        match self.consult(url, kid) {
157	            Consult::Key(key) => Ok(Some(key)),
158	            Consult::KnownAbsent => Ok(None),
159	            Consult::FailFast => Err(JwksError(format!(
160	                "JWKS fetch for {url} suppressed by refetch cooldown (recent attempt failed or is in flight)"
161	            ))),
162	            Consult::Fetch => {
163	                let set = self.fetcher.fetch(url).await?;
164	                let selected = select_key(&set, kid);
165	                self.store(url, set);
166	                Ok(selected)
167	            }
168	        }
169	    }
170	
171	    /// Consult the cache under one lock acquisition and decide how to resolve `(url, kid)`.
172	    ///
173	    /// When the decision is [`Consult::Fetch`], the attempt is stamped *before* the lock drops, so
174	    /// concurrent requests inside the cooldown window collapse onto one outbound fetch (the losers
175	    /// resolve from the cached set or fail fast rather than dogpiling the issuer).
176	    fn consult(&self, url: &str, kid: Option<&str>) -> Consult {
177	        let now = Instant::now();
178	        let mut entries = self.entries.lock().expect("jwks cache mutex poisoned");
179	        let Some(slot) = entries.get_mut(url) else {
180	            entries.insert(
181	                url.to_string(),
182	                CacheSlot {
183	                    last_attempt: now,
184	                    fetched: None,
185	                },
186	            );
187	            return Consult::Fetch;
188	        };
189	        let in_cooldown = now.duration_since(slot.last_attempt) < self.refetch_cooldown;
190	        let fresh = slot
191	            .fetched
192	            .as_ref()
193	            .filter(|cached| now.duration_since(cached.fetched_at) < self.ttl);
194	        if let Some(cached) = fresh {
195	            if let Some(key) = select_key(&cached.set, kid) {
196	                return Consult::Key(key);
197	            }
198	            // Fresh set without the kid: refetch (a rotation may have published it) unless the
199	            // cooldown says this kid stays negatively cached for now.
200	            if in_cooldown {
201	                return Consult::KnownAbsent;
202	            }
203	        } else if in_cooldown {
204	            // No usable set and too soon to try again — the last attempt failed (or is still in
205	            // flight), so answer like that failure instead of hammering the issuer.
206	            return Consult::FailFast;
207	        }
208	        slot.last_attempt = now;
209	        Consult::Fetch
210	    }
211	
212	    fn store(&self, url: &str, set: JwkSet) {
213	        let now = Instant::now();
214	        let mut entries = self.entries.lock().expect("jwks cache mutex poisoned");
215	        entries.insert(
216	            url.to_string(),
217	            CacheSlot {
218	                last_attempt: now,
219	                fetched: Some(CachedJwks {
220	                    fetched_at: now,
221	                    set,
222	                }),
223	            },
224	        );
225	    }
226	}
227	
228	/// Select a decoding key from a JWK set by `kid`. When the ID-JAG carries no `kid`, the choice is
229	/// unambiguous only if the set holds exactly one key. `None` when no key matches or the matched JWK
230	/// can't be converted to a decoding key (e.g. an unsupported key type).
231	fn select_key(set: &JwkSet, kid: Option<&str>) -> Option<DecodingKey> {
232	    let jwk = match kid {
233	        Some(kid) => set.find(kid)?,
234	        None => match set.keys.as_slice() {
235	            [only] => only,
236	            _ => return None,
237	        },
238	    };
239	    DecodingKey::from_jwk(jwk).ok()
240	}
241	
242	// ── Tests ─────────────────────────────────────────────────────────────────────────
243	
244	#[cfg(test)]
245	mod tests {
246	    use super::*;
247	    use std::sync::atomic::{AtomicUsize, Ordering};
248	
249	    use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
250	    use p256::ecdsa::SigningKey;
251	    use rand_core::OsRng;
252	    use serde_json::json;
253	
254	    /// A single-key P-256 JWK set carrying `kid`, valid for `DecodingKey::from_jwk`.
255	    fn jwks_with_kid(kid: &str) -> JwkSet {
256	        let sk = SigningKey::random(&mut OsRng);
257	        let point = sk.verifying_key().to_encoded_point(false);
258	        let x = URL_SAFE_NO_PAD.encode(point.x().unwrap());
259	        let y = URL_SAFE_NO_PAD.encode(point.y().unwrap());
260	        serde_json::from_value(json!({
261	            "keys": [{ "kty": "EC", "crv": "P-256", "x": x, "y": y, "kid": kid, "alg": "ES256", "use": "sig" }]
262	        }))
263	        .unwrap()
264	    }
265	
266	    /// A counting mock fetcher: returns the current `set` (or an error) and records how many times
267	    /// it ran. The set sits behind a `Mutex` so a test can swap it mid-flight (key rotation).
268	    struct MockFetcher {
269	        set: Arc<Mutex<JwkSet>>,
270	        calls: Arc<AtomicUsize>,
271	        fail: bool,
272	    }
273	
274	    impl JwksFetcher for MockFetcher {
275	        fn fetch<'a>(
276	            &'a self,
277	            _url: &'a str,
278	        ) -> Pin<Box<dyn Future<Output = Result<JwkSet, JwksError>> + Send + 'a>> {
279	            Box::pin(async move {
280	                self.calls.fetch_add(1, Ordering::SeqCst);
281	                if self.fail {
282	                    Err(JwksError("boom".to_string()))
283	                } else {
284	                    Ok(self.set.lock().unwrap().clone())
285	                }
286	            })
287	        }
288	    }
289	
290	    /// A cache over a mock fetcher with the given refetch cooldown (TTL fixed at 1h). Returns the
291	    /// swappable set handle and the fetch-call counter.
292	    fn cache_with_cooldown(
293	        set: JwkSet,
294	        fail: bool,
295	        cooldown: Duration,
296	    ) -> (JwksCache, Arc<Mutex<JwkSet>>, Arc<AtomicUsize>) {
297	        let calls = Arc::new(AtomicUsize::new(0));
298	        let set = Arc::new(Mutex::new(set));
299	        let fetcher = Arc::new(MockFetcher {
300	            set: set.clone(),
301	            calls: calls.clone(),
302	            fail,
303	        });
304	        (
305	            JwksCache::new(fetcher, Duration::from_secs(3600), cooldown),
306	            set,
307	            calls,
308	        )
309	    }
310	
311	    fn cache_with(set: JwkSet, fail: bool) -> (JwksCache, Arc<AtomicUsize>) {
312	        // Cooldown disabled: these tests exercise TTL/selection behavior, not the cooldown.
313	        let (cache, _set, calls) = cache_with_cooldown(set, fail, Duration::ZERO);
314	        (cache, calls)
315	    }
316	
317	    #[test]
318	    fn select_key_by_kid_matches() {
319	        let set = jwks_with_kid("k1");
320	        assert!(select_key(&set, Some("k1")).is_some());
321	    }
322	
323	    #[test]
324	    fn select_key_unknown_kid_is_none() {
325	        let set = jwks_with_kid("k1");
326	        assert!(select_key(&set, Some("other")).is_none());
327	    }
328	
329	    #[test]
330	    fn select_key_no_kid_single_key_is_ok() {
331	        let set = jwks_with_kid("k1");
332	        assert!(select_key(&set, None).is_some());
333	    }
334	
335	    #[test]
336	    fn select_key_no_kid_multiple_keys_is_ambiguous() {
337	        // Two keys, no kid to disambiguate → refuse rather than guess.
338	        let mut set = jwks_with_kid("k1");
339	        set.keys.push(jwks_with_kid("k2").keys.pop().unwrap());
340	        assert!(select_key(&set, None).is_none());
341	    }
342	
343	    #[tokio::test]
344	    async fn resolves_and_caches_within_ttl() {
345	        let (cache, calls) = cache_with(jwks_with_kid("k1"), false);
346	        assert!(cache
347	            .decoding_key("https://i/jwks", Some("k1"))
348	            .await
349	            .unwrap()
350	            .is_some());
351	        assert!(cache
352	            .decoding_key("https://i/jwks", Some("k1"))
353	            .await
354	            .unwrap()
355	            .is_some());
356	        // Second lookup is served from the cache — the fetcher ran exactly once.
357	        assert_eq!(calls.load(Ordering::SeqCst), 1);
358	    }
359	
360	    #[tokio::test]
361	    async fn unknown_kid_refetches_then_returns_none() {
362	        // With the cooldown disabled, a kid absent from the cached set forces a refetch (it could
363	        // be a freshly rotated key); when it's still absent, the resolution is `None`
364	        // (→ invalid_grant at the call site).
365	        let (cache, calls) = cache_with(jwks_with_kid("k1"), false);
366	        // Prime the cache with a hit so an entry exists.
367	        assert!(cache
368	            .decoding_key("https://i/jwks", Some("k1"))
369	            .await
370	            .unwrap()
371	            .is_some());
372	        assert!(cache
373	            .decoding_key("https://i/jwks", Some("missing"))
374	            .await
375	            .unwrap()
376	            .is_none());
377	        assert_eq!(
378	            calls.load(Ordering::SeqCst),
379	            2,
380	            "unknown kid must trigger a refetch"
381	        );
382	    }
383	
384	    #[tokio::test]
385	    async fn fetch_failure_is_error() {
386	        let (cache, _calls) = cache_with(jwks_with_kid("k1"), true);
387	        assert!(cache
388	            .decoding_key("https://i/jwks", Some("k1"))
389	            .await
390	            .is_err());
391	    }
392	
393	    #[tokio::test]
394	    async fn unknown_kid_burst_is_bounded_by_cooldown() {
395	        // The amplification vector: a stream of bogus kids for a trusted issuer. Within the
396	        // cooldown each one resolves negatively from the cached set — no outbound fetch per request.
397	        let (cache, _set, calls) =
398	            cache_with_cooldown(jwks_with_kid("k1"), false, Duration::from_secs(3600));
399	        assert!(cache
400	            .decoding_key("https://i/jwks", Some("k1"))
401	            .await
402	            .unwrap()
403	            .is_some());
404	        for i in 0..10 {
405	            assert!(cache
406	                .decoding_key("https://i/jwks", Some(&format!("bogus-{i}")))
407	                .await
408	                .unwrap()
409	                .is_none());
410	        }
411	        assert_eq!(
412	            calls.load(Ordering::SeqCst),
413	            1,
414	            "unknown kids within the cooldown must not refetch"
415	        );
416	        // A known key keeps resolving from the cache throughout.
417	        assert!(cache
418	            .decoding_key("https://i/jwks", Some("k1"))
419	            .await
420	            .unwrap()
421	            .is_some());
422	    }
423	
424	    #[tokio::test]
425	    async fn rotated_key_is_picked_up_after_cooldown() {
426	        // A genuine rotation publishes a new kid. Within the cooldown it reads as unknown; once
427	        // the cooldown lapses, the next request naming it triggers the refetch and resolves.
428	        let cooldown = Duration::from_millis(50);
429	        let (cache, set, calls) = cache_with_cooldown(jwks_with_kid("k1"), false, cooldown);
430	        assert!(cache
431	            .decoding_key("https://i/jwks", Some("k1"))
432	            .await
433	            .unwrap()
434	            .is_some());
435	        *set.lock().unwrap() = jwks_with_kid("k2");
436	        assert!(
437	            cache
438	                .decoding_key("https://i/jwks", Some("k2"))
439	                .await
440	                .unwrap()
441	                .is_none(),
442	            "inside the cooldown the rotated kid is still negatively cached"
443	        );
444	        assert_eq!(calls.load(Ordering::SeqCst), 1);
445	        tokio::time::sleep(cooldown + Duration::from_millis(20)).await;
446	        assert!(
447	            cache
448	                .decoding_key("https://i/jwks", Some("k2"))
449	                .await
450	                .unwrap()
451	                .is_some(),
452	            "after the cooldown the rotated kid must resolve via a refetch"
453	        );
454	        assert_eq!(calls.load(Ordering::SeqCst), 2);
455	    }
456	
457	    #[tokio::test]
458	    async fn fetch_failures_fail_fast_within_cooldown() {
459	        // A failing issuer (outage, timeout) is retried at most once per cooldown; requests inside
460	        // the window fail fast instead of each waiting out an outbound attempt.
461	        let (cache, _set, calls) =
462	            cache_with_cooldown(jwks_with_kid("k1"), true, Duration::from_secs(3600));
463	        for _ in 0..3 {
464	            assert!(cache
465	                .decoding_key("https://i/jwks", Some("k1"))
466	                .await
467	                .is_err());
468	        }
469	        assert_eq!(
470	            calls.load(Ordering::SeqCst),
471	            1,
472	            "repeat requests after a failed fetch must not retry within the cooldown"
473	        );
474	    }
475	
476	    #[tokio::test]
477	    async fn fetch_failure_retries_after_cooldown() {
478	        let cooldown = Duration::from_millis(50);
479	        let (cache, _set, calls) = cache_with_cooldown(jwks_with_kid("k1"), true, cooldown);
480	        assert!(cache
481	            .decoding_key("https://i/jwks", Some("k1"))
482	            .await
483	            .is_err());
484	        tokio::time::sleep(cooldown + Duration::from_millis(20)).await;
485	        assert!(cache
486	            .decoding_key("https://i/jwks", Some("k1"))
487	            .await
488	            .is_err());
489	        assert_eq!(
490	            calls.load(Ordering::SeqCst),
491	            2,
492	            "a lapsed cooldown must allow the retry"
493	        );
494	    }
495	}
